int32_t rf_predict(const float *features, int32_t features_length) {

        int32_t votes[8] = {0,};
        int32_t _class = -1;

        _class = rf_tree_0(features, features_length); votes[_class] += 1;
    _class = rf_tree_1(features, features_length); votes[_class] += 1;
    _class = rf_tree_2(features, features_length); votes[_class] += 1;
    _class = rf_tree_3(features, features_length); votes[_class] += 1;
    _class = rf_tree_4(features, features_length); votes[_class] += 1;
    _class = rf_tree_5(features, features_length); votes[_class] += 1;
    _class = rf_tree_6(features, features_length); votes[_class] += 1;
    _class = rf_tree_7(features, features_length); votes[_class] += 1;
    _class = rf_tree_8(features, features_length); votes[_class] += 1;
    _class = rf_tree_9(features, features_length); votes[_class] += 1;
    _class = rf_tree_10(features, features_length); votes[_class] += 1;
    _class = rf_tree_11(features, features_length); votes[_class] += 1;
    
        int32_t most_voted_class = -1;
        int32_t most_voted_votes = 0;
        for (int32_t i=0; i<8; i++) {

            if (votes[i] > most_voted_votes) {
                most_voted_class = i;
                most_voted_votes = votes[i];
            }
        }
        return most_voted_class;
    }
    

int rf_predict_proba(const float *features, int32_t features_length, float *out, int out_length) {

        int32_t _class = -1;

        for (int i=0; i<out_length; i++) {
            out[i] = 0.0f;
        }

        _class = rf_tree_0(features, features_length); out[_class] += 1.0f;
    _class = rf_tree_1(features, features_length); out[_class] += 1.0f;
    _class = rf_tree_2(features, features_length); out[_class] += 1.0f;
    _class = rf_tree_3(features, features_length); out[_class] += 1.0f;
    _class = rf_tree_4(features, features_length); out[_class] += 1.0f;
    _class = rf_tree_5(features, features_length); out[_class] += 1.0f;
    _class = rf_tree_6(features, features_length); out[_class] += 1.0f;
    _class = rf_tree_7(features, features_length); out[_class] += 1.0f;
    _class = rf_tree_8(features, features_length); out[_class] += 1.0f;
    _class = rf_tree_9(features, features_length); out[_class] += 1.0f;
    _class = rf_tree_10(features, features_length); out[_class] += 1.0f;
    _class = rf_tree_11(features, features_length); out[_class] += 1.0f;
    
        // compute mean
        for (int i=0; i<out_length; i++) {
            out[i] = out[i] / 12;
        }
        return 0;
    }
    